 *
 * Async because it reads a setting. Callers resolve it ONCE and pass it into
 * `retailCents`, which stays pure so the arithmetic is trivially checkable.
 */
export async function domainMarkupPct(): Promise<number> {
  const envDefault = Number(process.env.DOMAIN_MARKUP_PCT ?? DEFAULT_MARKUP_PCT);
